import numpy as np

def select_next_node(current_node, truck_nodes, depot_node, unvisited_nodes, distance_matrix):
    if len(unvisited_nodes) == 0:
        return depot_node

    nodes = list(unvisited_nodes)
    n = len(nodes)
    dist_current = distance_matrix[current_node, nodes]
    dist_sub = distance_matrix[np.ix_(nodes, nodes)]

    w = 0.5
    scores = np.zeros(n)
    for i, node in enumerate(nodes):
        other_dists = np.delete(dist_sub[i], i)
        if len(other_dists) == 0:
            std = 0.0
        else:
            std = np.std(other_dists)
        scores[i] = w * dist_current[i] + (1 - w) * std

    median_score = np.median(scores)
    min_idx = np.argmin(scores)
    if scores[min_idx] <= median_score:
        return nodes[min_idx]
    else:
        return next_node
